(45924, 'Genesis 50:26', 'Genesis', 50, 26, 'نو یوسف د یوسلو لس کالو په عمر په مصر کې مړ شو. وروسته له دې چې هغه یې مومیایي کړ، په تابوت کې یې کېښود.', 'نو یوسف د یوسلو لس کالو په عمر په مصر کې مر شو. وروسته له دې چې هغه یې مومیایی کر، په تابوت کې یې کېشود.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_50_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45925, 'Job 6:3', 'Job', 6, 3, 'ځکه چې دا به د سمندر د شګو نه درانۀ وى، نو په دې وجه زما خبرې ګډې وډې وې.', 'جکه چې دا به د سمندر د شګو نه درانۀ وی، نو په دې وجه زما خبرې ګدې ودې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45926, 'Job 6:4', 'Job', 6, 4, 'ځکه چې زۀ د قادر خُدائ په غشو باندې لګېدلے يم، د دې زهر زما په بدن کښې خوريږى، د خُدائ پاک افتونه په ما باندې راروان دى.', 'جکه چې زۀ د قادر خدای په غشو باندې لګېدلے یم، د دې زهر زما په بدن کشې خوریزی، د خدای پاک افتونه په ما باندې راروان دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45927, 'Job 6:5', 'Job', 6, 5, 'ولې زۀ د شکايت کولو حق نۀ لرم؟ ولې ځنګلى خرونه او غوَيى آواز نۀ کوى څۀ چې کله هغوئ خوراک نۀ لرى؟', 'ولې زۀ د شکایت کولو حق نۀ لرم؟ ولې جنګلی خرونه او غویی اواز نۀ کوی چۀ چې کله هغوی خوراک نۀ لری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45928, 'Job 6:6', 'Job', 6, 6, 'چې څۀ څيز بې‌خونده وى نو هغه د مالګې نه بغېر خوړلے شى څۀ، يا د هګۍ په سپينو کښې څۀ مزه شته؟', 'چې چۀ چیز بې‌خونده وی نو هغه د مالګې نه بغېر خورلے شی چۀ، یا د هګی په سپینو کشې چۀ مزه شته؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45929, 'Job 6:7', 'Job', 6, 7, 'کله چې زۀ دې ته وګورم نو زما لوږه ختمه شى، په داسې خوراک زۀ بيمارېږم.', 'کله چې زۀ دې ته وګورم نو زما لوزه ختمه شی، په داسې خوراک زۀ بیمارېزم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45930, 'Job 6:8', 'Job', 6, 8, 'کاش چې زما خواست منظور شى، او خُدائ پاک زما خواهش پوره کړى،', 'کاش چې زما خواست منظور شی، او خدای پاک زما خواهش پوره کری،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45931, 'Job 6:9', 'Job', 6, 9, 'زړۀ مې غواړى چې تباه مې کړى، او چې هغه خپل لاس راوږد کړى او ما ووژنى.', 'زرۀ مې غواری چې تباه مې کری، او چې هغه خپل لاس راوزد کری او ما ووژنی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45932, 'Job 6:10', 'Job', 6, 10, 'دا به زما دپاره تسلى وى، زۀ به په بې‌رحمه درد کښې هم خوشحاله يم، ځکه چې ما به بيا هم د مقدسې هستۍ د خبرو نه اِنکار نۀ وى کړے.', 'دا به زما دپاره تسلی وی، زۀ به په بې‌رحمه درد کشې هم خوشحاله یم، جکه چې ما به بیا هم د مقدسې هستی د خبرو نه انکار نۀ وی کرے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45933, 'Job 6:11', 'Job', 6, 11, 'زما دومره طاقت نشته چې زۀ دا برداشت کړم، او چې زما څۀ اُميد نشته نو بيا زۀ ولې ژوندے يم؟', 'زما دومره طاقت نشته چې زۀ دا برداشت کرم، او چې زما چۀ امید نشته نو بیا زۀ ولې ژوندے یم؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45934, 'Job 6:12', 'Job', 6, 12, 'زما طاقت لکه د کاڼو دے څۀ؟ زما بدن د اوسپنې نه جوړ دے څۀ؟', 'زما طاقت لکه د کانو دے چۀ؟ زما بدن د اوسپنې نه جور دے چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45935, 'Job 6:13', 'Job', 6, 13, 'په حقيقت کښې زۀ د خپل ځان سره د مدد کولو وس نۀ لرم، او خلاصون زما نه تلے دے.', 'په حقیقت کشې زۀ د خپل جان سره د مدد کولو وس نۀ لرم، او خلاصون زما نه تلے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45936, 'Job 6:14', 'Job', 6, 14, 'يو کس له په کار وى چې په خپل کمزورى دوست باندې رحم وکړى، خو تاسو سره د قادر خُدائ يره نۀ وى او په ما اِلزام لګوئ.', 'یو کس له په کار وی چې په خپل کمزوری دوست باندې رحم وکری، خو تاسو سره د قادر خدای یره نۀ وی او په ما الزام لګوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45937, 'Job 6:15', 'Job', 6, 15, 'زما وروڼو، تاسو ما سره د خوړ په شان دوکه بازى کوئ، چې کله باران نۀ وى نو دا اوچ شى.', 'زما ورونو، تاسو ما سره د خور په شان دوکه بازی کوی، چې کله باران نۀ وی نو دا اوچ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45938, 'Job 6:16', 'Job', 6, 16, 'چې د ويلې شوې واورې د اوبو نه ډک وى،', 'چې د ویلې شوې واورې د اوبو نه دک وی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45939, 'Job 6:17', 'Job', 6, 17, 'خو د ګرمۍ په وخت کښې دا اوبۀ اوچې شى، کله چې ګرمى شى، نو دا فنا شى.', 'خو د ګرمی په وخت کشې دا اوبۀ اوچې شی، کله چې ګرمی شی، نو دا فنا شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45940, 'Job 6:18', 'Job', 6, 18, 'د اوبو لټولو دپاره قافلې خپلې لارې بدلې کړى، خو د څښلو دپاره اوبۀ نۀ وى، نو هغوئ مړۀ شى.', 'د اوبو لتولو دپاره قافلې خپلې لارې بدلې کری، خو د چشلو دپاره اوبۀ نۀ وی، نو هغوی مرۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45941, 'Job 6:19', 'Job', 6, 19, 'د تيما قافلې دا اوبۀ لټوى، او د شيبا مسافر دا اُميد لرى چې اوبۀ به پېدا کړى.', 'د تیما قافلې دا اوبۀ لتوی، او د شیبا مسافر دا امید لری چې اوبۀ به پېدا کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45942, 'Job 6:20', 'Job', 6, 20, 'د قافلې يقين وى چې هغوئ به اوبۀ پېدا کړى، خو چې کله هلته ورسيږى نو هغوئ مايُوسه شى او اُميد يې ختم شى.', 'د قافلې یقین وی چې هغوی به اوبۀ پېدا کری، خو چې کله هلته ورسیزی نو هغوی مایوسه شی او امید یې ختم شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45943, 'Job 6:21', 'Job', 6, 21, 'اوس تاسو هم د دې اوچ خوړ په شان يئ چې بې‌کاره دے، تاسو زما مصيبت وليدلو او ويرېدئ.', 'اوس تاسو هم د دې اوچ خور په شان یی چې بې‌کاره دے، تاسو زما مصیبت ولیدلو او ویرېدی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45944, 'Job 6:22', 'Job', 6, 22, 'ولې ما وئيلى دى څۀ، چې ما له تُحفه راکړئ؟ يا مې د پېسو دپاره تا ته کله مِنت کړے دے څۀ؟', 'ولې ما وییلی دی چۀ، چې ما له تحفه راکری؟ یا مې د پېسو دپاره تا ته کله منت کرے دے چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45945, 'Job 6:23', 'Job', 6, 23, 'يا دا چې د دشمن د لاس نه مې بچ کړئ؟ يا د ظالمانو نه مې خلاص کړئ؟', 'یا دا چې د دشمن د لاس نه مې بچ کری؟ یا د ظالمانو نه مې خلاص کری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45946, 'Job 6:24', 'Job', 6, 24, 'ما ته وښايئ او زۀ به خاموش شم، ما پوهه کړئ چې زۀ څنګه په غلطه يم.', 'ما ته وشایی او زۀ به خاموش شم، ما پوهه کری چې زۀ چنګه په غلطه یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45947, 'Job 6:25', 'Job', 6, 25, 'رښتيا خبرې څومره د درد نه ډکې وى. خو ستاسو د دې بحث نه مطلب څۀ دے؟', 'رشتیا خبرې چومره د درد نه دکې وی. خو ستاسو د دې بحث نه مطلب چۀ دے؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45948, 'Job 6:26', 'Job', 6, 26, 'ستاسو خيال دا دے څۀ چې زما خبرې به صحيح کړئ، او د نا اُميده سړى خبرې بې‌مطلبه ګڼئ؟', 'ستاسو خیال دا دے چۀ چې زما خبرې به صحیح کری، او د نا امیده سری خبرې بې‌مطلبه ګنی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45949, 'Job 6:27', 'Job', 6, 27, 'تاسو به يتيمان هم خرڅ کړئ، او تاسو به د خپل دوست په سر هم پېسې واخلئ.', 'تاسو به یتیمان هم خرچ کری، او تاسو به د خپل دوست په سر هم پېسې واخلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45950, 'Job 6:28', 'Job', 6, 28, 'خو اوس ما ته وګورئ، ولې زۀ به تاسو ته دروغ وايم څۀ؟', 'خو اوس ما ته وګوری، ولې زۀ به تاسو ته دروغ وایم چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45951, 'Job 6:29', 'Job', 6, 29, 'خپل سوچ بدل کړئ او بې‌اِنصافه مۀ جوړېږئ، داسې وګڼئ چې زۀ په حقه يم.', 'خپل سوچ بدل کری او بې‌انصافه مۀ جورېزی، داسې وګنی چې زۀ په حقه یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_6_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
